PRAGMA foreign_keys = ON;
CREATE TABLE IF NOT EXISTS accounts (account_number TEXT PRIMARY KEY, payload_json TEXT NOT NULL, synced_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS meters (id INTEGER PRIMARY KEY, fuel TEXT NOT NULL CHECK(fuel IN ('electricity','gas')), point_id TEXT NOT NULL, serial_number TEXT NOT NULL, tariff_code TEXT, valid_from TEXT, valid_to TEXT, synced_at TEXT NOT NULL, UNIQUE(fuel,point_id,serial_number));
CREATE TABLE IF NOT EXISTS consumption (meter_id INTEGER NOT NULL REFERENCES meters(id), interval_start TEXT NOT NULL, interval_end TEXT NOT NULL, consumption_kwh REAL NOT NULL, PRIMARY KEY(meter_id,interval_start,interval_end));
CREATE TABLE IF NOT EXISTS tariff_rates (meter_id INTEGER NOT NULL REFERENCES meters(id), kind TEXT NOT NULL CHECK(kind IN ('standard-unit-rates','standing-charges')), valid_from TEXT NOT NULL, valid_to TEXT, value_inc_vat REAL NOT NULL, PRIMARY KEY(meter_id,kind,valid_from));
CREATE TABLE IF NOT EXISTS daily_costs (date TEXT NOT NULL, fuel TEXT NOT NULL, consumption_kwh REAL NOT NULL, unit_cost_gbp REAL NOT NULL, standing_charge_gbp REAL NOT NULL, total_cost_gbp REAL NOT NULL, PRIMARY KEY(date,fuel));
CREATE TABLE IF NOT EXISTS anomalies (id INTEGER PRIMARY KEY, detected_at TEXT NOT NULL, date TEXT NOT NULL, fuel TEXT NOT NULL, kind TEXT NOT NULL, detail TEXT NOT NULL, UNIQUE(date,fuel,kind));
CREATE TABLE IF NOT EXISTS savings_recommendations (id INTEGER PRIMARY KEY, created_at TEXT NOT NULL, category TEXT NOT NULL, recommendation TEXT NOT NULL, estimated_gbp REAL, UNIQUE(created_at,category));
CREATE TABLE IF NOT EXISTS sync_history (id INTEGER PRIMARY KEY, started_at TEXT NOT NULL, ended_at TEXT, status TEXT NOT NULL, electricity_records INTEGER NOT NULL DEFAULT 0, gas_records INTEGER NOT NULL DEFAULT 0, error_category TEXT);
